selector_to_html = {"a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.viz.injector_viz\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.injector_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.injector_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Injector scenes and face views.</p><p><a class=\"reference internal\" href=\"InjectorComponent.html#pyskyfire.viz.injector_viz.InjectorComponent\" title=\"pyskyfire.viz.injector_viz.InjectorComponent\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorComponent</span></code></a> draws the wetted surface of every hole, its bore\nbehind the face, one colour per feed, optionally carrying each hole\u2019s flow from\nan <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorResult</span></code> as scene fields. Arrows from\neach hole to its impingement point can be added; they are annotation, not\nhardware.\n<a class=\"reference internal\" href=\"#pyskyfire.viz.injector_viz.plot_injector_face\" title=\"pyskyfire.viz.injector_viz.plot_injector_face\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">plot_injector_face()</span></code></a> is the same injector seen from the chamber: hole\noutlines, the jets projected onto the face, and where they meet.</p>", "a[href=\"InjectorComponent.html#pyskyfire.viz.injector_viz.InjectorComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.injector_viz.InjectorComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.injector_viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">InjectorComponent</span></span></dt><dd><p>Display the wetted bores of an injector\u2019s holes, coloured by feed.</p><p class=\"rubric\">Notes</p><p>Only wetted surface is drawn as hardware. A hole\u2019s bore runs back from the\nface along its axis for the orifice\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">length</span></code>, or two diameters where\nno length is given, and ends where it meets the face plane. The arrows\nare drawn in grey, without fields, as annotation. The <code class=\"docutils literal notranslate\"><span class=\"pre\">face</span></code> anchor sits\non the axis at the face, pointing into the chamber.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.viz.injector_viz.FEED_COLORS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.injector_viz.FEED_COLORS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.injector_viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FEED_COLORS</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">('#2a78d6',</span> <span class=\"pre\">'#eb6834',</span> <span class=\"pre\">'#1baf7a',</span> <span class=\"pre\">'#eda100',</span> <span class=\"pre\">'#e87ba4',</span> <span class=\"pre\">'#008300')</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.viz.injector_viz.plot_injector_face\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.injector_viz.plot_injector_face\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.injector_viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">plot_injector_face</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">injector</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">face_radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">colors</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">labels</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The injector seen from the chamber, in millimetres.</p><p>Each hole\u2019s outline on the face is drawn in its feed\u2019s colour, with its\njet projected onto the face as a line to the impingement point, where a\ngrey dot marks where the jets meet. <code class=\"docutils literal notranslate\"><span class=\"pre\">face_radius</span></code> adds the chamber wall\nas a grey circle. Hovering a hole shows its set, feed and diameter.</p><p>Parameters are as for <a class=\"reference internal\" href=\"InjectorComponent.html#pyskyfire.viz.injector_viz.InjectorComponent\" title=\"pyskyfire.viz.injector_viz.InjectorComponent\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorComponent</span></code></a>.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
